import cats.effect.{IO, IOApp, Outcome}
import scala.concurrent.duration._

object FiberSupervisor extends IOApp.Simple {
  val worker: IO[Unit] = IO.sleep(1.second) >> IO.println("Worker executed")
  val run: IO[Unit] = for {
    fiber <- worker.start
    _     <- IO.println("Fiber spawned concurrently")
    _     <- fiber.join.flatMap {
      case Outcome.Succeeded(fa) => fa
      case Outcome.Errored(e)    => IO.println(s"Failed: ${e.getMessage}")
      case Outcome.Canceled()    => IO.println("Fiber canceled")
    }
  } yield ()
}

import cats.effect.{IO, Resource}
import java.sql.{Connection, DriverManager}

def acquireConnection(url: String): Resource[IO, Connection] =
  Resource.make(
    IO.blocking(DriverManager.getConnection(url))
  )(conn => IO.blocking(conn.close()).handleErrorWith(_ => IO.unit))

