import cats.MonadThrow
import cats.syntax.all._

trait OrderRepository[F[_]]:
  def findOrder(id: String): F[Option[String]]
  def saveOrder(id: String, amount: Double): F[Unit]

class CheckoutService[F[_]: MonadThrow](repo: OrderRepository[F]):
  def checkout(id: String, amount: Double): F[Unit] =
    repo.findOrder(id).flatMap {
      case Some(_) => MonadThrow[F].raiseError(new IllegalStateException("Duplicate order"))
      case None    => repo.saveOrder(id, amount)
    }

import cats.effect.{IO, IOApp}
import fs2.{Stream, Pipe}
import scala.concurrent.duration._

object Fs2Pipeline extends IOApp.Simple {
  val ticker: Stream[IO, Long] = Stream.awakeEvery[IO](100.millis).map(_.toMillis)
  val processor: Pipe[IO, Long, String] = _.map(ts => s"Event emitted at: $ts")

  val run: IO[Unit] = ticker.through(processor).take(10).evalMap(IO.println).compile.drain
}

