import cats.effect.{IO, Ref, Deferred}

sealed trait State
case object Idle extends State
case class Busy(task: String) extends State

class JobRunner(stateRef: Ref[IO, State]) {
  def assign(task: String): IO[Boolean] =
    stateRef.modify {
      case Idle    => (Busy(task), true)
      case Busy(_) => (Busy(task), false)
    }
}

